(() => {
  const game = (id,set,title,titleZh,clues,prompt,promptZh,options,answer,explanation,explanationZh,hint) => ({id,set,title,titleZh,bankLabel:'Grammar clues · 文法提示',phraseBank:clues,prompt,promptZh,options,answer,explanation,explanationZh,hint});
  const item = (id,format,formatZh,contextTitle,context,prompt,promptZh,options,answer,explanation,explanationZh,hint) => ({id,format,formatZh,contextTitle,context,prompt,promptZh,options,answer,explanation,explanationZh,hint});

  window.S1_S3_GRAMMAR_EXPANSION = {
    games:[
      game('s1-pv01','passive','Passive Voice Quest 1: The notice','被動語態闖關 1：通告',['be + past participle','focus on the action','school notice'],'The library rules _____ to every new student in September.','圖書館規則於九月派發給每位新生。',['are given','give','are giving','given'],0,'Rules receive the action, so use the present passive: are given.','規則是接受動作的對象，所以用現在式被動語態 are given。','What receives the action? 哪個名詞接受動作？'),
      game('s1-pv02','passive','Passive Voice Quest 1: Yesterday’s event','被動語態闖關 1：昨天的活動',['was/were + past participle','yesterday = past','event report'],'The sports prizes _____ by the principal yesterday.','獎項昨天由校長頒發。',['were presented','presented','are presented','were presenting'],0,'Yesterday needs the past passive: were presented.','yesterday 表示過去，所以用過去式被動語態 were presented。','Find the past-time clue. 找出過去時間提示。'),
      game('s1-pv03','passive','Passive Voice Quest 1: Who did it?','被動語態闖關 1：誰做了？',['by + agent','passive voice','school project'],'The mural was painted _____ the art club.','壁畫由美術學會繪畫。',['by','with','from','at'],0,'Use by to name the person or group that did the action.','用 by 表示執行動作的人或團體。','Who painted the mural? 誰繪畫壁畫？'),
      game('s1-pv04','passive','Passive Voice Quest 1: Keep it safe','被動語態闖關 1：保持安全',['must be + past participle','rule','passive form'],'All borrowed tablets must _____ returned by Friday.','所有借用的平板電腦必須在星期五前歸還。',['be','are','being','to be'],0,'After must, use be + past participle in a passive rule.','must 後的被動規則用 be + 過去分詞。','The tablets receive the returning action. 平板是被歸還的對象。'),
      game('s1-pv05','passive','Passive Voice Quest 1: Planned change','被動語態闖關 1：計劃改變',['will be + past participle','future notice','action receiver'],'The old water fountain _____ replaced next month.','舊飲水機下月會被更換。',['will be','will','is','will being'],0,'Use will be + past participle for a future passive action.','未來被動動作用 will be + 過去分詞。','Next month points to the future. next month 指向未來。'),
      game('s1-pv06','passive','Passive Voice Quest 1: Choose the focus','被動語態闖關 1：選擇焦點',['receiver first','passive sentence','school message'],'Which sentence best focuses on the lost keys?','哪一句最能把焦點放在遺失的鑰匙上？',['The lost keys were found near the hall.','A student found the lost keys near the hall.','A student is finding lost keys near the hall.','The keys found a student near the hall.'],0,'The passive sentence begins with the lost keys, the receiver of the action.','被動句以遺失的鑰匙開始，焦點在接受動作的對象。','What is the message mainly about? 訊息主要講甚麼？'),
      game('s1-pv07','passive','Passive Voice Quest 2: Recycling day','被動語態闖關 2：回收日',['are collected','routine action','plural subject'],'Plastic bottles _____ every Thursday after lunch.','塑膠樽每逢星期四午飯後收集。',['are collected','collect','are collecting','were collected'],0,'A regular routine with plural bottles uses are collected.','定期習慣加上複數 bottles 用 are collected。','Every Thursday is a routine clue. every Thursday 表示定期。'),
      game('s1-pv08','passive','Passive Voice Quest 2: A completed job','被動語態闖關 2：完成的工作',['was completed','past event','singular subject'],'The noticeboard _____ before the visitors arrived.','告示板在訪客到達前已完成佈置。',['was completed','completed','is completed','was completing'],0,'The noticeboard is singular and the job finished in the past: was completed.','noticeboard 是單數，工作在過去完成：was completed。','Is the job done by the board or to the board? 動作是告示板做還是發生在告示板上？'),
      game('s1-pv09','passive','Passive Voice Quest 2: Not allowed','被動語態闖關 2：不被允許',['cannot be + past participle','rule','passive prohibition'],'Food _____ eaten in the computer room.','電腦室內不可進食。',['cannot be','cannot','is not','does not'],0,'A passive rule uses cannot be + past participle.','被動規則用 cannot be + 過去分詞。','Food receives the eating action. 食物是被吃的對象。'),
      game('s1-pv10','passive','Passive Voice Quest 2: Improve a message','被動語態闖關 2：改善訊息',['clear notice','passive form','formal school message'],'Choose the best revision: “Someone checks the entrance at 7:30.”','選擇最佳修訂：「有人在七時三十分檢查入口。」',['The entrance is checked at 7:30.','The entrance checks at 7:30.','The entrance is checking at 7:30.','The entrance checked someone at 7:30.'],0,'The revision makes the entrance-checking action the focus.','修訂後把入口檢查這項行動放在焦點。','Use passive voice when the action matters more than the person. 當行動比執行者重要時用被動語態。'),
      game('s1-pv11','passive','Passive Voice Quest 2: Keep the tense','被動語態闖關 2：保持時態',['present passive','every day','be + past participle'],'Lunch cards _____ at the gate every day.','午餐卡每天在閘門口查核。',['are checked','were checked','check','are checking'],0,'Every day needs a present routine, so use are checked.','every day 表示現在的習慣，所以用 are checked。','Match the tense to the time phrase. 把時態配合時間詞。'),
      game('s1-pv12','passive','Passive Voice Quest 2: Final check','被動語態闖關 2：最後檢查',['passive question','was/were','action receiver'],'_____ the emergency lights tested last week?','緊急照明燈上星期有被測試嗎？',['Were','Did','Was','Are'],0,'Lights are plural and receive the action, so ask Were they tested?','lights 是複數並且接受動作，所以問 Were they tested?','Count the noun first. 先數名詞數量。'),
      game('s1-c01','conditionals','Conditionals Quest 1: A general rule','條件句闖關 1：一般規則',['if + present','present result','zero conditional'],'If you _____ a library book, you show your card at the desk.','如果你借圖書館書籍，便在櫃檯出示借書證。',['borrow','will borrow','borrowed','are borrowing'],0,'Use present simple for a general rule after if.','一般規則的 if 後用簡單現在式。','Is this always true or only tomorrow? 這是一般規則還是只說明天？'),
      game('s1-c02','conditionals','Conditionals Quest 1: A likely result','條件句闖關 1：可能結果',['if + present','will + base verb','future result'],'If the rain stops, we _____ the garden activity outside.','如果雨停，我們會在戶外進行園藝活動。',['will continue','continue','continued','will continued'],0,'A likely future result uses will + base verb in the main clause.','可能的未來結果在主句用 will + 動詞原形。','Find the future result. 找出未來結果。'),
      game('s1-c03','conditionals','Conditionals Quest 1: Check the if clause','條件句闖關 1：檢查 if 分句',['if + present simple','not will','first conditional'],'If students _____ the instructions, the task will be safer.','如果學生閱讀指示，任務會更安全。',['read','will read','readed','are read'],0,'Do not use will in the if clause of a first conditional.','第一類條件句的 if 分句不用 will。','Which clause has will? 哪個分句有 will？'),
      game('s1-c04','conditionals','Conditionals Quest 1: Give advice','條件句闖關 1：提出建議',['if + present','imperative result','classroom rule'],'If you finish early, _____ your partner politely.','如果你提早完成，請有禮地幫助同伴。',['help','will help','helped','helping'],0,'A rule can use if + present followed by an imperative.','規則可用 if + 現在式，再接祈使句。','The second part gives an instruction. 第二部分提出指示。'),
      game('s1-c05','conditionals','Conditionals Quest 1: Avoid an accident','條件句闖關 1：避免意外',['if + present','will + base verb','safety result'],'If we leave bags in the corridor, someone _____ trip over them.','如果我們把書包留在走廊，有人可能會絆倒。',['will','is','did','has'],0,'Use will + base verb for the likely result.','可能的結果用 will + 動詞原形。','What may happen later? 之後可能發生甚麼？'),
      game('s1-c06','conditionals','Conditionals Quest 1: Choose the message','條件句闖關 1：選擇訊息',['first conditional','future plan','clear sequence'],'Which message is correct?','哪個訊息正確？',['If the hall is free, we will practise there.','If the hall will be free, we practise there.','If the hall was free, we will practise there.','If the hall is free, we will practised there.'],0,'Use if + present simple and will + base verb.','用 if + 簡單現在式及 will + 動詞原形。','Check both halves of the sentence. 檢查句子的兩部分。'),
      game('s1-c07','conditionals','Conditionals Quest 2: A science rule','條件句闖關 2：科學規則',['zero conditional','if + present','present result'],'If water _____ below 0°C, it freezes.','如果水降至零度以下，它會結冰。',['falls','will fall','fell','is falling'],0,'A science fact uses present simple in both clauses.','科學事實的兩個分句都用簡單現在式。','This is a general fact. 這是一般事實。'),
      game('s1-c08','conditionals','Conditionals Quest 2: Plan a reminder','條件句闖關 2：計劃提醒',['first conditional','present in if clause','future result'],'If you _____ the form today, the teacher will read it tomorrow.','如果你今天交表格，老師明天會閱讀。',['submit','will submit','submitted','submitting'],0,'Today in the if clause still needs present simple.','if 分句即使說今天也用簡單現在式。','Do not add will after if. if 後不要加 will。'),
      game('s1-c09','conditionals','Conditionals Quest 2: Match the result','條件句闖關 2：配對結果',['if + present','will result','school action'],'If the class collects enough cans, we _____ them to the recycling centre.','如果班級收集到足夠鋁罐，我們會把它們送到回收中心。',['will take','take','took','will taking'],0,'Use will take for the planned future result.','計劃的未來結果用 will take。','Which part describes the result? 哪個部分描述結果？'),
      game('s1-c10','conditionals','Conditionals Quest 2: Fix the error','條件句闖關 2：改正錯誤',['first conditional','will in main clause','edit a notice'],'Choose the best correction: “If you will need help, ask the office.”','選擇最佳修正：「如果你將會需要幫助，請問辦事處。」',['If you need help, ask the office.','If you needed help, will ask the office.','If you need help, you asking the office.','If you will need help, you will ask the office.'],0,'In a condition clause, use need, not will need.','條件分句用 need，不用 will need。','Remove will from the if clause. 從 if 分句移除 will。'),
      game('s1-c11','conditionals','Conditionals Quest 2: Work together','條件句闖關 2：共同合作',['if + present','will + base verb','team result'],'If everyone shares one idea, the plan _____ stronger.','如果每人分享一個想法，計劃會更好。',['will become','becomes','became','will became'],0,'The main clause needs will + base verb: will become.','主句需要 will + 動詞原形：will become。','Look after will. 看 will 後面。'),
      game('s1-c12','conditionals','Conditionals Quest 2: Final decision','條件句闖關 2：最終決定',['condition + result','future','clear proposal'],'If the trial is successful, the school _____ a longer programme.','如果試行成功，學校會考慮較長的計劃。',['will consider','considers','considered','will considered'],0,'Use will consider for a possible future decision.','可能的未來決定用 will consider。','The trial result comes first; the decision follows. 先有試行結果，再有決定。')
    ],
    s1Grammar:{questions:[
      item('s1-gb01','Complete the message','完成訊息','School repair notice','The main hall is closed today because new lights are being installed.','The work _____ by 4 p.m. if there are no delays.','如果沒有延誤，工程下午四時前會完成。',['will be completed','will complete','is completing','completed'],0,'The work receives the action, so use future passive: will be completed.','工程是接受動作的對象，所以用未來被動語態 will be completed。','Look for the receiver of the action. 找出接受動作的對象。'),
      item('s1-gb02','Choose the best correction','選擇最佳修正','Class monitor message','A student wrote: “The new posters put up yesterday.”','Which correction is best?','哪個修正最好？',['The new posters were put up yesterday.','The new posters were putting up yesterday.','The new posters put up yesterday.','The new posters are put up yesterday.'],0,'Use were + past participle for plural posters in a past passive sentence.','複數 posters 的過去被動句用 were + 過去分詞。','Plural posters need were. 複數 posters 用 were。'),
      item('s1-gb03','Use the time clue','運用時間線索','Club invitation','The drama club started rehearsals in March and is still preparing.','The drama club _____ for the show since March.','戲劇學會自三月起一直為演出準備。',['has prepared','has been preparing','prepared','is prepare'],1,'Since March with an ongoing action can use present perfect continuous: has been preparing.','since March 加上持續動作可用現在完成進行式 has been preparing。','The work started before now and continues. 工作在現在之前開始並持續。'),
      item('s1-gb04','Check the sentence','檢查句子','School science day','Which sentence is grammatically accurate?','哪一句文法正確？',['The experiments were explained by the science team.','The experiments was explained by the science team.','The science team were explain the experiments.','The experiments are explain by the science team.'],0,'Experiments is plural, so use were explained.','experiments 是複數，所以用 were explained。','Match the be verb to the plural noun. 把 be 動詞配合複數名詞。'),
      item('s1-gb05','Transform the notice','轉換通告','Lost-property notice','The office found a blue umbrella near the hall.','Which passive version keeps the meaning?','哪個被動語態版本保持原意？',['A blue umbrella was found near the hall.','A blue umbrella found the office near the hall.','A blue umbrella is finding near the hall.','The office was found by a blue umbrella.'],0,'The umbrella receives the finding action, so it becomes the subject in the passive version.','雨傘接受被找到的動作，所以在被動版本中成為主語。','Move the thing receiving the action to the front. 把接受動作的事物放在句首。'),
      item('s1-gb06','Complete the message','完成訊息','Weather plan','The forecast says there may be heavy rain on Friday.','If it _____ heavily, the class will use the indoor court.','如果雨勢很大，班級會使用室內球場。',['rains','will rain','rained','is raining'],0,'Use present simple after if for a likely future result.','可能的未來結果在 if 後用簡單現在式。','Do not use will after if. if 後不要用 will。'),
      item('s1-gb07','Choose the best correction','選擇最佳修正','Recycling instruction','A student wrote: “If you will bring a bottle, use the blue bin.”','Which correction is best?','哪個修正最好？',['If you bring a bottle, use the blue bin.','If you brought a bottle, will use the blue bin.','If you will bring a bottle, you use the blue bin.','If you bringing a bottle, use the blue bin.'],0,'Use bring, not will bring, in the if clause.','if 分句用 bring，不用 will bring。','This is an instruction after a condition. 這是條件後的指示。'),
      item('s1-gb08','Use the clue','運用線索','Student helper schedule','Mina is checking visitor name tags now. Yesterday, she welcomed parents at the gate.','Which sentence describes Mina now?','哪一句描述 Mina 現在的情況？',['She is checking name tags.','She checked name tags.','She checks name tags yesterday.','She has check name tags.'],0,'Now signals present continuous: is checking.','now 表示現在進行式：is checking。','Match the tense to now. 把時態配合 now。'),
      item('s1-gb09','Edit for clarity','編輯得更清楚','Community garden report','The class visited the garden. A volunteer showed the class how to compost.','Which sentence combines the ideas accurately?','哪一句能準確合併兩個意思？',['A volunteer showed the class how to compost at the garden.','The garden showed a volunteer how to compost.','A volunteer who composted the class was at the garden.','The class showed the volunteer was garden.'],0,'The volunteer did the showing, and the class received the explanation.','義工負責示範，班級接受講解。','Identify who did each action. 找出誰做每個動作。'),
      item('s1-gb10','Check the sentence','檢查句子','Reading club form','Which sentence uses a gerund correctly?','哪一句正確使用動名詞？',['I enjoy reading mystery stories.','I enjoy to read mystery stories.','I enjoy read mystery stories.','I enjoying read mystery stories.'],0,'Enjoy is followed by a gerund: enjoy reading.','enjoy 後接動名詞：enjoy reading。','Remember the verb pattern after enjoy. 記住 enjoy 後的動詞形式。'),
      item('s1-gb11','Complete the message','完成訊息','Helping plan','The class wants to help a new student find rooms.','We decided _____ a simple map.','我們決定製作一張簡單地圖。',['to make','making','make','made'],0,'Decide is followed by to + base verb: to make.','decide 後接 to + 動詞原形：to make。','Decide to do something. 決定做某事。'),
      item('s1-gb12','Use the time clue','運用時間線索','School trip update','The group left the school at 8:00 and arrived at the museum at 9:00.','By 9:00, the group _____ at the museum.','到九時，小組已到達博物館。',['had arrived','has arrived','arrives','will arrive'],0,'By a past time, use past perfect for the earlier completed action.','在過去時間前完成的動作用過去完成式。','Which action was complete by 9:00? 哪個動作在九時前完成？'),
      item('s1-gb13','Choose the best correction','選擇最佳修正','Comparison board','A student wrote: “The library is more quieter than the canteen.”','Which correction is best?','哪個修正最好？',['The library is quieter than the canteen.','The library is more quietest than the canteen.','The library is quiet than the canteen.','The library is most quieter than the canteen.'],0,'Use quieter than, not more quieter.','用 quieter than，不用 more quieter。','Do not use two comparative markers. 不要同時用兩個比較級標記。'),
      item('s1-gb14','Complete the message','完成訊息','Visitor guide','The school has welcomed visitors every term since 2024.','It _____ more than 300 visitors since then.','自 2024 年起，學校已接待超過三百名訪客。',['has welcomed','welcomed','welcomes','had welcomed'],0,'Since then connects past time to now, so use present perfect: has welcomed.','since then 連接過去至現在，所以用現在完成式 has welcomed。','Look for since. 找出 since。'),
      item('s1-gb15','Check the sentence','檢查句子','Safety sign','Which sentence gives a clear safety rule?','哪一句提出清晰安全規則？',['Bags must not be left in the corridor.','Bags must not left in the corridor.','Bags do not must be left in the corridor.','Bags must not leaving in the corridor.'],0,'Must not be + past participle makes a clear passive safety rule.','must not be + 過去分詞構成清晰的被動安全規則。','Use be after must not. must not 後用 be。'),
      item('s1-gb16','Transform the notice','轉換通告','Library reminder','The librarian will check each returned book tomorrow.','Which sentence keeps the same meaning?','哪一句保持相同意思？',['Each returned book will be checked tomorrow.','Each returned book will check tomorrow.','Each returned book is checking tomorrow.','Each returned book checked tomorrow.'],0,'The books receive the action, so use will be checked.','書籍是接受動作的對象，所以用 will be checked。','Future passive = will be + past participle. 未來被動 = will be + 過去分詞。'),
      item('s1-gb17','Edit for clarity','編輯得更清楚','Club poster','Which sentence gives a polite request?','哪一句提出有禮請求？',['Could you tell me where the music room is?','Could you told me where is the music room?','Could you telling me where the music room?','Could you to tell me where is the music room?'],0,'Could you + base verb is polite; the indirect question uses statement order.','Could you + 動詞原形很有禮；間接問句用直述句語序。','After where, use music room is. where 後用 music room is。'),
      item('s1-gb18','Use the clue','運用線索','Study plan','The group will print the survey only after all members agree.','The group will print the survey if everyone _____.','如果所有成員同意，小組便會列印問卷。',['agrees','will agree','agreed','agreeing'],0,'Everyone is singular, so use agrees in the if clause.','everyone 是單數，所以 if 分句用 agrees。','Check both the condition and subject number. 檢查條件與主語數量。'),
      item('s1-gb19','Complete the message','完成訊息','New-student guide','The guide should be short and useful.','How _____ information should the guide include?','指引應簡短而有用。它應包括多少資料？',['much','many','few','a few'],0,'Information is uncountable, so use how much.','information 不可數，所以用 how much。','Can you count information as separate objects? information 可以當作獨立物件來數嗎？'),
      item('s1-gb20','Choose the best correction','選擇最佳修正','Club invitation','A student wrote: “We need an useful idea for the welcome game.”','Which correction is best?','哪個修正最好？',['We need a useful idea for the welcome game.','We need an useful idea for the welcome game.','We need the useful idea for welcome game.','We need useful an idea for the welcome game.'],0,'Useful begins with a consonant sound /j/, so use a useful idea.','useful 以子音音素 /j/ 開始，所以用 a useful idea。','Listen to the first sound, not only the first letter. 留意首個發音，不只是首個字母。'),
      item('s1-gb21','Use the time clue','運用時間線索','Reading challenge','Mina joined the reading challenge in September and still takes part.','Mina _____ in the reading challenge since September.','Mina 自九月起一直參加閱讀挑戰。',['has taken part','took part','is taking part yesterday','had taken part'],0,'Since September connects the past start to now, so use has taken part.','since September 把過去開始時間連接至現在，所以用 has taken part。','The activity started before now and continues. 活動在現在之前開始並持續。'),
      item('s1-gb22','Check the sentence','檢查句子','Rainy-day journey','Which sentence describes an action in progress when another action happened?','哪一句描述另一動作發生時正在進行的動作？',['I was walking to school when the rain started.','I walked to school when the rain was start.','I was walk to school when the rain started.','I have walking to school when the rain started.'],0,'Use was walking for the action in progress and started for the shorter past event.','正在進行的動作用 was walking，較短的過去事件用 started。','Which action was already happening? 哪個動作當時已正在進行？'),
      item('s1-gb23','Transform the notice','轉換通告','Student helper list','A student helps new classmates find their rooms.','Which sentence joins the ideas accurately?','哪一句能準確連結兩個意思？',['The student who helps new classmates is a class helper.','The student which helps new classmates is a class helper.','The student who new classmates helps is a class helper.','The student helps who new classmates is a class helper.'],0,'Use who for a person doing the action; the relative clause follows student.','用 who 指做動作的人；關係子句放在 student 後。','The clause describes a person. 子句修飾一個人。'),
      item('s1-gb24','Edit for clarity','編輯得更清楚','Library poster','The library is quiet. Students can concentrate there.','Which sentence joins the ideas with a reason?','哪一句用原因連接兩個意思？',['Students can concentrate in the library because it is quiet.','Students can concentrate in the library because it quiet.','Students can concentrate in the library so because it is quiet.','Because students can concentrate the library is quiet.'],0,'Because introduces a reason with a complete subject and verb: it is quiet.','because 引入包含完整主語和動詞的原因：it is quiet。','The second clause should answer why students can concentrate. 第二個分句應回答學生為何能專心。')
    ]},
    s2Grammar:{questions:[
      item('s2-gb01','Complete the message','完成訊息','Programme report','The survey team finished collecting replies before the meeting started.','Before the meeting, the team _____ 86 replies.','會議前，團隊已收集 86 份回覆。',['had collected','has collected','collects','will collect'],0,'Past perfect shows the collection happened before the later past meeting.','過去完成式表示收集發生在較後的過去會議之前。','Compare the two past actions. 比較兩個過去動作。'),
      item('s2-gb02','Choose the best correction','選擇最佳修正','Website update','A student wrote: “The report has published on the website.”','Which correction is best?','哪個修正最好？',['The report has been published on the website.','The report has publish on the website.','The report has publishing on the website.','The report was publishing on the website.'],0,'Use has been + past participle for present perfect passive.','現在完成式被動用 has been + 過去分詞。','The report receives the publishing action. 報告是被發布的對象。'),
      item('s2-gb03','Transform the notice','轉換通告','Source check','The editor checked the date before sharing the post.','Which reported sentence is accurate?','哪個轉述句正確？',['The editor said that she had checked the date.','The editor said that she has checked the date.','The editor said that she check the date.','The editor said that she will checked the date.'],0,'A past report can backshift the earlier action to had checked.','過去轉述可把較早動作後移為 had checked。','The checking happened before the reporting. 核實發生在轉述之前。'),
      item('s2-gb04','Check the sentence','檢查句子','Community plan','Which sentence uses a defining relative clause correctly?','哪一句正確使用限定性關係子句？',['Students who join the review group will compare ideas.','Students which join the review group will compare ideas.','Students who they join the review group will compare ideas.','Students join who the review group will compare ideas.'],0,'Use who for people and do not repeat the subject pronoun.','人用 who，而且不要重複主語代名詞。','The clause describes students. 子句修飾 students。'),
      item('s2-gb05','Use the clue','運用線索','Trial proposal','The school may run a small pilot in October.','If the pilot _____ useful feedback, the school will extend it.','如果試行帶來有用回饋，學校會延長計劃。',['provides','will provide','provided','had provided'],0,'Use present simple after if in a first conditional.','第一類條件句的 if 後用簡單現在式。','The extension is the future result. 延長是未來結果。'),
      item('s2-gb06','Choose the best correction','選擇最佳修正','Hypothetical option','A student wrote: “If the school will have more space, it would add a study zone.”','Which correction is best?','哪個修正最好？',['If the school had more space, it would add a study zone.','If the school has more space, it would add a study zone.','If the school will have more space, it will adding a study zone.','If the school had more space, it will add a study zone.'],0,'An imagined present situation uses if + past simple and would + base verb.','想像的現在情況用 if + 過去式及 would + 動詞原形。','Is this a real plan or a hypothetical option? 這是真實計劃還是假設選項？'),
      item('s2-gb07','Complete the message','完成訊息','Evidence note','The class collected comments to understand different views.','The class collected comments _____ understand different views.','班級收集意見以了解不同觀點。',['to','for','so','because'],0,'To + base verb expresses purpose.','to + 動詞原形表達目的。','Why did the class collect comments? 為何收集意見？'),
      item('s2-gb08','Edit for a formal response','編輯正式回應','Feedback email','Which sentence is the most careful claim?','哪一句是最謹慎的主張？',['The results may suggest a need for clearer signs.','The results prove that every student needs clearer signs.','The results are suggesting every student.','The results may to suggest clearer signs.'],0,'May suggest is careful because a survey may have limits.','may suggest 很謹慎，因為調查可能有限制。','Avoid claiming that limited evidence proves everything. 避免說有限證據證明所有事情。'),
      item('s2-gb09','Check the sentence','檢查句子','Volunteer report','Which sentence uses a participle phrase accurately?','哪一句正確使用分詞片語？',['Using the feedback, the team revised its plan.','Using the feedback, the plan revised the team.','Used the feedback, the team revising its plan.','Using the feedback, the team was revise its plan.'],0,'The team used the feedback, so it is the subject after the opening phrase.','團隊使用回饋，所以開首分詞片語後的主語是團隊。','Who is doing the using? 誰正在使用回饋？'),
      item('s2-gb10','Complete the message','完成訊息','Attendance report','The school has run the pilot _____ four weeks.','學校已進行試行四星期。',['for','since','during','from'],0,'Use for with a length of time.','表示一段時間用 for。','Four weeks is a duration. four weeks 是一段時間。'),
      item('s2-gb11','Choose the best correction','選擇最佳修正','Data summary','A student wrote: “Less students attended the late session.”','Which correction is best?','哪個修正最好？',['Fewer students attended the late session.','Little students attended the late session.','Much students attended the late session.','Least students attended the late session.'],0,'Use fewer with countable plural students.','可數複數 students 用 fewer。','Can you count students? students 可以數嗎？'),
      item('s2-gb12','Transform the notice','轉換通告','Safety information','Staff will inspect the accessible entrance every day.','Which passive version is correct?','哪個被動版本正確？',['The accessible entrance will be inspected every day.','The accessible entrance will inspect every day.','The accessible entrance is inspecting every day.','The accessible entrance has inspect every day.'],0,'Future passive uses will be inspected.','未來被動用 will be inspected。','The entrance receives the action. 入口接受動作。'),
      item('s2-gb13','Use the clue','運用線索','Discussion rule','The group wants to discuss every idea fairly.','Each member should _____ one reason for a suggestion.','每位成員應為建議提出一個理由。',['give','gives','to give','giving'],0,'Should is followed by a base verb.','should 後接動詞原形。','A modal needs the base form. 情態動詞需要原形。'),
      item('s2-gb14','Check the sentence','檢查句子','Formal request','Which sentence is most appropriate for a formal email?','哪一句最適合正式電郵？',['I would appreciate it if you could consider our request.','I want you consider our request now.','You should to consider our request.','Consider our request, please, immediately.'],0,'Would appreciate it if you could is polite and formal.','would appreciate it if you could 有禮而正式。','Choose the respectful request. 選擇尊重的請求。'),
      item('s2-gb15','Complete the message','完成訊息','Media note','The post is useful, _____ it does not name its writer.','帖文有用，但沒有列出作者。',['although','therefore','so that','because of'],0,'Although introduces a contrast or limitation.','although 引入對比或限制。','The second clause limits the first. 第二個分句限制第一個。'),
      item('s2-gb16','Edit for a formal response','編輯正式回應','Proposal sentence','Which sentence has parallel structure?','哪一句有平行結構？',['The proposal aims to improve access, reduce waste and collect feedback.','The proposal aims to improve access, reducing waste and feedback collection.','The proposal aims improving access, reduce waste and to collect feedback.','The proposal aims to improve access, waste reduction and collect feedback.'],0,'Keep the three verbs in the same to + base form pattern.','三個動詞保持相同的 to + 動詞原形結構。','Look for a matching list pattern. 找出一致的列表結構。'),
      item('s2-gb17','Use the clue','運用線索','Survey reminder','The teacher asked, “Have you completed the form?”','How should the reminder be reported?','提示應如何轉述？',['The teacher asked whether we had completed the form.','The teacher asked whether have we completed the form.','The teacher asked whether we complete the form.','The teacher asked whether we had complete the form.'],0,'Reported questions use statement order; have completed can backshift to had completed.','轉述問句用直述句語序；have completed 可後移為 had completed。','Do not invert we and had. 不要倒裝 we 和 had。'),
      item('s2-gb18','Choose the best correction','選擇最佳修正','Review meeting','A student wrote: “The plan is more practical because it includes a backup step.”','Which revision adds a fair limitation?','哪個修訂加入公平限制？',['The plan may be more practical because it includes a backup step, although costs still need checking.','The plan proves it is perfect because it includes a backup step.','The plan more practical includes a backup step.','The plan is practical although it will cost none.'],0,'May and although make the claim balanced and acknowledge a remaining question.','may 和 although 令主張平衡，並承認仍有問題。','A good evaluation names both strength and limit. 好的評估會說明優點和限制。')
    ]},
    s3Grammar:{questions:[
      item('s3-gb01','Edit for a formal response','編輯正式回應','Formal report','The report summarises student views from a small poll.','Which sentence is the most cautious report?','哪一句是最謹慎的報告句？',['The poll may indicate that some students need a quieter space.','The poll proves that all students need a quieter space.','The poll is indicating every student.','The poll may to indicate all students.'],0,'May indicate and some students avoid overgeneralising a limited poll.','may indicate 和 some students 避免把有限調查過度概括。','Check the size and limits of the evidence. 檢查證據的規模和限制。'),
      item('s3-gb02','Transform the notice','轉換通告','Programme update','People believe that the pilot will improve access.','Which formal passive version is accurate?','哪個正式被動版本正確？',['The pilot is believed to improve access.','The pilot believes to improve access.','The pilot is believing improve access.','The pilot believed that improves access.'],0,'A reporting passive can be formed with is believed to + base verb.','報告被動可用 is believed to + 動詞原形。','The belief is reported, not held by the pilot. 這是對信念的報告，不是試行本身相信。'),
      item('s3-gb03','Choose the best correction','選擇最佳修正','Evidence comparison','A student wrote: “Having reviewed the two sources, the differences was clear.”','Which correction is best?','哪個修正最好？',['Having reviewed the two sources, the team found the differences clear.','Having reviewed the two sources, the differences found clear.','Having reviewed the two sources, the differences was clear.','Having reviewed the two sources, the team finding the differences.'],0,'The team reviewed the sources, so it must be the subject after the opening phrase.','團隊核對來源，所以它必須是開首片語後的主語。','Avoid a dangling opening phrase. 避免懸垂的開首片語。'),
      item('s3-gb04','Complete the message','完成訊息','Proposal draft','The school has limited evidence about evening transport.','If the school _____ more family feedback, it would make a better decision.','如果學校有更多家庭回饋，便會作出更佳決定。',['had','has','will have','had had'],0,'This imagined present situation uses if + past simple and would + base verb.','這個想像的現在情況用 if + 過去式及 would + 動詞原形。','The school does not have enough feedback now. 現在學校沒有足夠回饋。'),
      item('s3-gb05','Use the clue','運用線索','Review reflection','The team did not collect transport data, so it cannot compare routes now.','Which sentence explains the missed opportunity?','哪一句解釋錯過的機會？',['If the team had collected transport data, it could compare routes now.','If the team collected transport data, it can compare routes now.','If the team had collected transport data, it will compare routes now.','If the team collects transport data, it could compare routes now.'],0,'A past condition with a present result uses had collected + could compare.','過去條件配合現在結果用 had collected + could compare。','The missing action was in the past; the effect is now. 缺少的行動在過去，影響在現在。'),
      item('s3-gb06','Check the sentence','檢查句子','Research summary','Which sentence uses nominalisation appropriately?','哪一句恰當使用名詞化？',['The evaluation of the pilot should include access and transport.','The evaluate of the pilot should include access and transport.','The pilot should be evaluation access and transport.','The evaluation should evaluate the pilot access.'],0,'Evaluation is the noun form used in a formal summary.','evaluation 是正式摘要中使用的名詞形式。','Look for the noun after The. 留意 The 後的名詞。'),
      item('s3-gb07','Edit for a formal response','編輯正式回應','Email recommendation','Which sentence has the most precise formal tone?','哪一句有最準確的正式語氣？',['We recommend that the school conduct a limited, reviewed trial.','We think the school should just do the thing.','The school conducting a trial is good.','We recommend the school to conducting a trial.'],0,'Recommend that + subject + base verb is formal and precise.','recommend that + 主語 + 動詞原形正式而準確。','Choose precise proposal language. 選擇準確的建議書語言。'),
      item('s3-gb08','Complete the message','完成訊息','Source note','The resident message was written last year and has no update date.','The message, _____ may no longer be current, should be checked.','該居民訊息可能已不再是最新，應被核實。',['which','who','where','whose'],0,'Which refers to the message, a thing.','which 指事物，這裡指 message。','What does the clause describe? 子句描述甚麼？'),
      item('s3-gb09','Choose the best correction','選擇最佳修正','Data statement','A student wrote: “The number of responses were limited.”','Which correction is best?','哪個修正最好？',['The number of responses was limited.','The number of responses were limited.','The responses number was limited.','The number of response were limited.'],0,'The head noun is number, which is singular.','中心名詞是 number，屬單數。','Find the main noun, not the noun after of. 找出中心名詞，不是 of 後的名詞。'),
      item('s3-gb10','Transform the notice','轉換通告','Formal finding','The school reviewed attendance, access and feedback.','Which sentence keeps a parallel list?','哪一句保持平行列表？',['The school reviewed attendance, access and feedback.','The school reviewed attendance, accessing and feedback.','The school reviewed attendance, access and to collect feedback.','The school reviewed attending, access and feedback.'],0,'All three items are nouns, so the list is parallel.','三項都是名詞，所以列表平行。','Keep items in the same grammar form. 保持項目使用相同文法形式。'),
      item('s3-gb11','Use the clue','運用線索','Policy reflection','The proposal must protect access, but it should not make claims beyond the evidence.','Which sentence meets both aims?','哪一句同時符合兩個目標？',['The proposal should protect access and may require further transport evidence.','The proposal proves transport is never a problem.','The proposal must to protect access and may to require evidence.','The proposal protects access because it has no evidence.'],0,'Should and may create a responsible recommendation with an acknowledged limit.','should 和 may 形成負責任的建議並承認限制。','Use modals with base verbs. 情態動詞後用原形。'),
      item('s3-gb12','Check the sentence','檢查句子','Briefing note','Which sentence uses a reduced clause accurately?','哪一句正確使用簡化子句？',['Students using the study space will sign in at the desk.','Students use the study space will sign in at the desk.','Students used the study space will sign in at the desk.','Students are using the study space will sign in at the desk.'],0,'Using the study space reduces who use the study space.','using the study space 是 who use the study space 的簡化形式。','The students perform the using action. 學生執行使用的動作。'),
      item('s3-gb13','Complete the message','完成訊息','Review report','The pilot ended in June, and the team has already compared the results.','The team _____ the results before writing its recommendation.','團隊在撰寫建議前已比較結果。',['had compared','has compared','compares','will compare'],0,'The comparison happened before the later past writing, so use had compared.','比較在較後的過去撰寫前發生，所以用 had compared。','Which action happened first? 哪個動作先發生？'),
      item('s3-gb14','Edit for a formal response','編輯正式回應','Recommendation conclusion','Which conclusion is most balanced?','哪個結論最平衡？',['On balance, a limited extension is recommended, provided that access checks continue.','On balance, the plan is perfect and needs no review.','On balance, extending is recommend because everything good.','On balance, the plan must be perfect.'],0,'Provided that states a condition and keeps the recommendation careful.','provided that 提出條件，令建議保持謹慎。','A balanced conclusion includes a safeguard. 平衡結論包括保障。'),
      item('s3-gb15','Choose the best correction','選擇最佳修正','Source evaluation','A student wrote: “Not having a date, the post should not share.”','Which correction is best?','哪個修正最好？',['Because the post has no date, it should not be shared without checking.','Not having a date, the post should not share.','The post not having a date should not sharing.','Because no date, the post should not share.'],0,'The post receives the sharing action, so use should not be shared; the reason clause needs a subject and verb.','帖文是被分享的對象，所以用 should not be shared；原因分句需要主語和動詞。','Check both the reason and passive form. 檢查原因分句和被動形式。'),
      item('s3-gb16','Use the clue','運用線索','Audience purpose','The principal needs a concise recommendation, not a casual chat message.','Which opening best matches the audience and purpose?','哪個開首最符合受眾和目的？',['I am writing to recommend a limited trial based on the attached findings.','Hey, I have a random idea about the library.','The library trial is good, maybe, I guess.','You should do this now because I say so.'],0,'The first opening states purpose, tone and evidence clearly.','第一個開首清楚說明目的、語氣和證據。','Match formality to the reader. 配合讀者使用正式語氣。'),
      item('s3-gb17','Check the sentence','檢查句子','Evidence paragraph','Which sentence links evidence and interpretation clearly?','哪一句清楚連結證據和解釋？',['Although 138 students wanted the space, the survey did not show every family’s view.','Although 138 students wanted the space, so every family agreed.','138 students wanted the space because the survey although.','The survey 138 students wanted although.'],0,'Although introduces evidence followed by a relevant limitation.','although 引入證據後再接相關限制。','A responsible paragraph includes a limit. 負責任段落包括限制。'),
      item('s3-gb18','Transform the notice','轉換通告','Final proposal','The school will collect comments and check access before deciding.','Which sentence expresses the same sequence most clearly?','哪一句最清楚表達相同次序？',['Before making a decision, the school will collect comments and check access.','Before the school will decide, it collects comments and check access.','The school decides before it will collect comments.','Before making a decision, the school collected comments and will check access.'],0,'Before + -ing can introduce the first action; the main clause states the future plan.','before + 動名詞可引入先做的動作；主句說明未來計劃。','Keep the future meaning in the main clause. 把未來意思放在主句。'),
      item('s3-gb19','Select the strongest evidence-based revision','選擇最有證據基礎的修訂','Noise-feedback summary','Of 64 student comments, 41 mentioned noise, but the form did not ask families for views.','Which revision reports the finding most responsibly?','哪個修訂最負責任地報告這項發現？',['The comments suggest that noise may be a concern, although family views still need collecting.','The comments prove that every family is worried about noise.','Noise is certainly the only problem because 41 students said so.','All families dislike the space, according to the student comments.'],0,'The best revision reports the pattern carefully and names the missing family evidence.','最佳修訂謹慎報告趨勢，並指出缺少家庭意見這項限制。','Keep both the useful evidence and its limit. 同時保留有用證據和其限制。'),
      item('s3-gb20','Complete the formal synthesis','完成正式綜合句','Two-source review','The attendance log records late arrivals, and the student form asks for clearer closing-time notices.','Taken together, the sources _____ that a trial may need clearer evening guidance.','綜合而言，這些來源 _____ 試行可能需要更清楚的晚間指引。',['suggest','suggests','are suggest','to suggesting'],0,'Sources is plural, so use suggest. The phrase taken together signals a synthesis rather than two separate summaries.','sources 是複數，所以用 suggest。taken together 表示綜合資料，而非分開摘要。','Check the number of the subject, then link both sources. 先檢查主語數量，再連結兩個來源。'),
      item('s3-gb21','Choose the accurate inference','選擇準確推論','Follow-up survey','A short poll shows that 32 of 50 respondents prefer a later library closing time.','Which inference matches the evidence without overclaiming?','哪項推論既符合證據又不過度概括？',['The pattern may warrant a short follow-up survey with more respondents.','Every student wants the library to close later.','The poll settles the decision for all families.','The school should remove all other study options immediately.'],0,'A limited poll can justify a next step for collecting more evidence, not a final claim about everyone.','有限調查可支持下一步蒐集更多證據，不能對所有人作最終結論。','Ask what the evidence can reasonably support next. 問自己證據下一步可合理支持甚麼。'),
      item('s3-gb22','Edit a source-qualifying sentence','修訂來源限定句','Online announcement','A student wrote: “Although the flyer says the rule is new, it is correct.”','Which revision is most precise?','哪個修訂最精準？',['Although the flyer refers to a new rule, its date and issuing organisation should be checked.','Although the flyer says new, it is certainly correct.','The flyer, although new rule, should correct.','Although the flyer is correct, no source needs checking.'],0,'The revision keeps the flyer as a possible source but asks for date and organisation checks before treating it as reliable.','修訂保留海報作為可能來源，但要求先核對日期及發布機構，才視為可靠。','A source claim needs traceable details. 來源主張需要可追溯的資料。'),
      item('s3-gb23','Complete the formal recommendation','完成正式建議','Entrance review','The morning entrance becomes crowded between 7:50 and 8:05.','Given the observation data, the school recommends that two volunteers _____ at the gate.','根據觀察資料，學校建議兩名義工 _____ 在閘口。',['be assigned','are assigned','assigned','to assigning'],0,'After recommends that, formal proposal English can use a base-form passive: be assigned.','在 recommends that 後，正式建議英文可使用原形被動：be assigned。','The volunteers receive the assignment action. 義工是接受分配動作的對象。'),
      item('s3-gb24','Complete the formal concession','完成正式讓步句','Pilot review','The pilot reduced crowding at the gate. Several families still reported difficulties with the later collection time.','_____ the pilot reduced crowding, the transport concern requires further review.','_____ 試行減少了閘口擠擁，接送交通的關注仍需進一步檢討。',['Although','Therefore','Unless','So that'],0,'Although allows the writer to recognise a benefit while keeping a separate concern visible.','although 讓作者承認好處，同時保持另一項關注清楚可見。','A formal evaluation can hold two true points together. 正式評估可同時保留兩個真實重點。'),
      item('s3-gb25','Edit a condition for action','修訂行動條件','Extension criteria','The school will consider extending the study-space service after the review.','The service should be extended only if attendance records _____ consistent demand.','只有當出席紀錄 _____ 持續需求時，才應延長服務。',['show','shows','showing','to show'],0,'Attendance records is plural, so use show. The if clause states the evidence condition for an action.','attendance records 是複數，所以用 show。if 分句說明採取行動所需的證據條件。','Check the plural subject and the condition for action. 檢查複數主語和行動條件。'),
      item('s3-gb26','Choose the precise reporting verb','選擇精準報告動詞','Attendance pattern','The number of late arrivals fell during the four-week pilot, but the school has not compared a longer period.','Which sentence reports the pattern most carefully?','哪一句最謹慎地報告這個趨勢？',['The pilot appears to have reduced late arrivals during the review period.','The pilot has completely solved late arrivals forever.','The pilot proves that no student will be late again.','The pilot is reducing every possible problem.'],0,'Appears to have reports a possible completed effect without claiming certainty beyond the review period.','appears to have 報告可能已完成的效果，而不超出檢討期間作出肯定主張。','Match certainty to the length and limits of the data. 把肯定程度配合資料的時間長度和限制。'),
      item('s3-gb27','Complete the formal emphasis','完成正式強調句','Access report','The plan improved the accessible path and gave families clearer pickup information.','Not only _____ access, but it also provided clearer pickup information.','該計劃不但 _____ 通道，亦提供了更清楚的接送資訊。',['did the plan improve','the plan improved','the plan did improve','improved the plan'],0,'After the limiting opener Not only, use auxiliary inversion: did the plan improve.','在限制性開首 Not only 後使用助動詞倒裝：did the plan improve。','Look for did before the subject in this emphasis structure. 在此強調結構中留意主語前的 did。'),
      item('s3-gb28','Complete a concise formal noun phrase','完成精煉正式名詞片語','Feedback review','The committee needs to study comments from students, families and staff in an organised way.','The committee requested a _____ of the feedback before deciding.','委員會要求在作決定前先對回饋作 _____。',['systematic analysis','systematically analyse','systematic analyse','systematically analysis'],0,'A noun phrase is needed after a. Systematic analysis is concise and suits a formal report.','a 後需要名詞片語。systematic analysis 精煉且適合正式報告。','Check which option can follow a and name the action formally. 檢查哪個選項可接在 a 後，並以正式方式命名行動。'),
      item('s3-gb29','Strengthen textual reference','加強文本指代','Sign-in data','Sign-ins rose by 12% during the trial. A student wrote: “This might show that the change helped.”','Which revision makes the reference clearest?','哪個修訂令指代最清楚？',['This 12% increase in sign-ins may indicate that the change helped during the trial.','This may show it helped, maybe.','The thing may help that.','It proves the change helped everyone.'],0,'Naming the 12% increase makes the evidence reference clear and keeps may indicate appropriately cautious.','點出 12% 的登記增幅可令證據指代清楚，並以 may indicate 保持適度謹慎。','Replace vague this or it with the exact evidence you mean. 用確切證據取代含糊的 this 或 it。'),
      item('s3-gb30','Select the balanced closing','選擇平衡結語','Consultation conclusion','The school has useful student feedback but has not yet collected views from every family.','Which closing best matches the evidence?','哪個結語最符合證據？',['In light of the limited sample, the proposal should be a starting point for further consultation rather than a final decision.','The proposal is final because the student feedback is enough.','All families agree, so no consultation is needed.','The evidence proves that every concern has disappeared.'],0,'The strongest closing values the available evidence while making clear that further consultation is needed.','最有力的結語重視已有證據，同時清楚說明仍需要進一步諮詢。','End with a proportionate next step, not an unsupported final claim. 結尾應提出合乎比例的下一步，而非沒有根據的最終主張。')
    ]},
    s3FormalResponseAnalysis:{
      's3-gb01':{focus:'Hedging and evidence scope',focusZh:'謹慎語氣與證據範圍',steps:['Spot the limit: the evidence comes from a small poll.','Choose a tentative reporting verb: may indicate.','Limit the group with some students, not all students.'],stepsZh:['先找出限制：證據來自小型調查。','選用暫定報告動詞：may indicate。','用 some students 限定對象，不寫 all students。'],transfer:'In a formal response, separate what the evidence shows from what you can reasonably claim.',transferZh:'在正式回應中，分清證據顯示甚麼，以及你可合理作出的主張。'},
      's3-gb02':{focus:'Passive reporting for formal summaries',focusZh:'正式摘要的報告被動語態',steps:['Identify the reporting verb: people believe.','Move the focus to the pilot, not to unnamed people.','Use is believed to + base verb.'],stepsZh:['找出報告動詞：people believe。','把焦點放在試行，而非未指明的人。','使用 is believed to + 動詞原形。'],transfer:'Reporting passives help formal reports foreground a finding when the reporter is not important.',transferZh:'當報告者並非重點時，報告被動語態可讓正式報告凸顯發現。'},
      's3-gb03':{focus:'Control the subject after an opening phrase',focusZh:'控制開首片語後的主語',steps:['Ask who reviewed the two sources: the team.','Place that doer immediately after the opening phrase.','Keep differences plural and use clear as the complement.'],stepsZh:['先問誰核對兩個來源：the team。','把這個動作執行者放在開首片語後。','保留複數 differences，並以 clear 作補語。'],transfer:'Check every opening -ing phrase: its implied doer must match the main-clause subject.',transferZh:'檢查每個 -ing 開首片語：其隱含執行者必須與主句主語一致。'},
      's3-gb04':{focus:'Second conditional for an imagined present',focusZh:'用第二類條件句表達假設現在',steps:['The school lacks enough feedback now.','Use if + past simple for an unreal present condition.','Match it with would + base verb in the result.'],stepsZh:['學校現在缺乏足夠回饋。','假設現在情況用 if + 過去式。','結果部分配合 would + 動詞原形。'],transfer:'Use a second conditional to test an option that is not currently available.',transferZh:'使用第二類條件句去評估目前未能實行的選項。'},
      's3-gb05':{focus:'Mixed conditional: past evidence, present consequence',focusZh:'混合條件句：過去證據、現在結果',steps:['The missing data collection happened in the past.','Use had collected for that unreal past action.','Use could compare now for its present consequence.'],stepsZh:['缺少的資料收集行動發生在過去。','該假設過去動作用 had collected。','其現在結果用 could compare now。'],transfer:'Mixed conditionals help a formal evaluation explain how an earlier choice affects a current decision.',transferZh:'混合條件句可協助正式評估解釋早前選擇如何影響現時決定。'},
      's3-gb06':{focus:'Nominalisation for a formal report',focusZh:'正式報告中的名詞化',steps:['The sentence needs a noun after The.','Change evaluate into the noun evaluation.','Keep the meaning specific with of the pilot.'],stepsZh:['The 後需要名詞。','把 evaluate 改成名詞 evaluation。','以 of the pilot 保持意思具體。'],transfer:'Nominalisation can make a report concise, but it should still name the action or evidence clearly.',transferZh:'名詞化可令報告更精煉，但仍應清楚指出行動或證據。'},
      's3-gb07':{focus:'Recommendation clause and formal register',focusZh:'建議子句與正式語體',steps:['Look for the formal trigger recommend that.','Use a clear subject: the school.','Use the base verb conduct after that-clause recommendation.'],stepsZh:['留意正式提示詞 recommend that。','使用清楚主語：the school。','建議子句後用動詞原形 conduct。'],transfer:'A precise recommendation names the action, keeps a measured tone and avoids vague wording.',transferZh:'精準建議應指明行動、維持適度語氣，並避免含糊措辭。'},
      's3-gb08':{focus:'Non-defining relative clause for qualification',focusZh:'用非限定關係子句補充限制',steps:['The clause adds information about message, a thing.','Use which after the comma.','Read the extra information as a reason to verify the message.'],stepsZh:['這個子句補充說明事物 message。','逗號後使用 which。','把補充資料理解為需要核實訊息的原因。'],transfer:'Use a non-defining clause to add a concise limitation without interrupting the main report point.',transferZh:'可使用非限定關係子句簡潔加入限制，而不打斷報告主旨。'},
      's3-gb09':{focus:'Head-noun agreement in data statements',focusZh:'數據句的中心名詞一致',steps:['Ignore the plural noun after of at first.','Find the head noun: number.','Use singular was to match number.'],stepsZh:['先暫時忽略 of 後的複數名詞。','找出中心名詞：number。','以單數 was 配合 number。'],transfer:'In formal data writing, check agreement against the head noun, especially in of-phrases.',transferZh:'正式數據寫作要按中心名詞配合單複數，尤其注意 of 片語。'},
      's3-gb10':{focus:'Parallel structure in a findings list',focusZh:'發現列表的平行結構',steps:['Identify the first two list items: attendance and access.','Both are nouns.','Choose feedback, another noun, to complete the list.'],stepsZh:['找出前兩個列表項目：attendance 和 access。','兩者都是名詞。','選用同為名詞的 feedback 完成列表。'],transfer:'Keep lists in the same grammar form so a proposal is easy to read and logically balanced.',transferZh:'讓列表維持相同文法形式，使建議書易讀且邏輯平衡。'},
      's3-gb11':{focus:'Modal verbs, caution and limitation',focusZh:'情態動詞、謹慎語氣與限制',steps:['Keep the first duty with should + base verb: protect.','Use may + base verb: require.','Choose a phrase that admits the evidence gap.'],stepsZh:['第一項責任用 should + 動詞原形：protect。','使用 may + 動詞原形：require。','選取承認證據不足的說法。'],transfer:'A responsible recommendation can state an action and a remaining evidence need in the same sentence.',transferZh:'負責任的建議可在同一句說明行動及仍需補充的證據。'},
      's3-gb12':{focus:'Reduced relative clause',focusZh:'簡化關係子句',steps:['Start with the full idea: students who use the study space.','Reduce who use to using.','Keep students as the doer of using.'],stepsZh:['先還原完整意思：students who use the study space。','把 who use 簡化為 using。','保持 students 是 using 的執行者。'],transfer:'Reduced clauses make formal notes more concise when the implied subject stays clear.',transferZh:'隱含主語清楚時，簡化子句可令正式筆記更精煉。'},
      's3-gb13':{focus:'Past-perfect sequencing in a report',focusZh:'報告中的過去完成式排序',steps:['Place the comparison before the later past action of writing.','Use had compared for the earlier completed action.','Use the time phrase before writing to confirm the sequence.'],stepsZh:['把比較放在較後的過去動作 writing 之前。','較早完成的動作用 had compared。','用 before writing 確認時序。'],transfer:'Use the past perfect only when a report needs to make two past stages unmistakably clear.',transferZh:'只有在報告需要清楚區分兩個過去階段時才用過去完成式。'},
      's3-gb14':{focus:'Qualified conclusion with a safeguard',focusZh:'含保障條件的審慎結論',steps:['A balanced conclusion should not call the plan perfect.','Choose a limited extension, not an unlimited claim.','Add provided that to state the continuing access check.'],stepsZh:['平衡結論不應說計劃完美。','選擇有限延長，而非無限制主張。','用 provided that 說明持續進行的通道檢查。'],transfer:'A formal recommendation is stronger when it names both an action and the condition for continuing it.',transferZh:'正式建議同時說明行動和持續條件時會更有說服力。'},
      's3-gb15':{focus:'Reason clause plus passive obligation',focusZh:'原因分句加被動責任句',steps:['Make the reason a full clause: the post has no date.','The post receives the sharing action.','Use should not be shared without checking.'],stepsZh:['把原因寫成完整分句：the post has no date。','帖文是接受分享動作的對象。','使用 should not be shared without checking。'],transfer:'When evaluating a source, explain the reason and then state the cautious action in a complete sentence.',transferZh:'評估來源時，先完整說明原因，再在完整句中提出謹慎行動。'},
      's3-gb16':{focus:'Audience, purpose and formal opening',focusZh:'受眾、目的與正式開首',steps:['The reader is a principal who needs a concise recommendation.','State the purpose directly: I am writing to recommend.','Mention the evidence basis without becoming casual.'],stepsZh:['讀者是需要簡潔建議的校長。','直接說明目的：I am writing to recommend。','提及證據基礎，同時保持正式。'],transfer:'Match register to audience by naming purpose, action and evidence in the opening sentence.',transferZh:'按受眾配合語體：在開首句說明目的、行動和證據。'},
      's3-gb17':{focus:'Concession: evidence with a clear limit',focusZh:'讓步：證據配合清楚限制',steps:['Keep the useful evidence: 138 students wanted the space.','Introduce the limitation with Although.','Avoid turning one survey into every family’s view.'],stepsZh:['保留有用證據：138 名學生希望有該空間。','以 Although 引入限制。','避免把一項調查當成每個家庭的意見。'],transfer:'A strong formal paragraph can acknowledge evidence and its boundary together.',transferZh:'有力的正式段落可同時承認證據及其限制。'},
      's3-gb18':{focus:'Sequence a future decision clearly',focusZh:'清楚排列未來決定的次序',steps:['The evidence gathering happens before the decision.','Use Before + -ing to introduce that earlier stage.','Keep will collect and check in the future main clause.'],stepsZh:['收集證據發生在作決定之前。','使用 Before + -ing 引出較早階段。','把 will collect 和 check 保留在表達未來的主句。'],transfer:'Use clear sequence markers to show that a recommendation depends on a review process.',transferZh:'使用清楚的順序標記，說明建議取決於檢討程序。'},
      's3-gb19':{focus:'Evidence-based revision with a stated limitation',focusZh:'附有限制說明的證據修訂',steps:['Separate the evidence from the claim: 41 of 64 student comments mentioned noise.','Choose suggest and may be a concern because the data is limited.','Add the missing perspective: family views were not collected.','Reject options that turn a student sample into every family’s view.'],stepsZh:['先分開證據和主張：64 份學生意見中有 41 份提及噪音。','資料有限，所以選擇 suggest 和 may be a concern。','加入缺少的角度：尚未收集家庭意見。','排除把學生樣本當成所有家庭意見的選項。'],transfer:'In senior-secondary formal responses, a strong revision preserves the useful finding and names the evidence boundary.',transferZh:'在高中階段正式回應中，有力的修訂會保留有用發現，並說明證據界線。'},
      's3-gb20':{focus:'Synthesize two sources accurately',focusZh:'準確綜合兩個來源',steps:['Identify the two inputs: attendance records and a student request form.','Use Taken together to signal synthesis, not repetition.','Match the plural subject sources with suggest.','Keep the conclusion tentative: may need clearer guidance.'],stepsZh:['找出兩項資料：出席紀錄和學生要求表。','使用 Taken together 表示綜合，而非重複資料。','複數主語 sources 配合 suggest。','結論保持暫定：may need clearer guidance。'],transfer:'Integrated responses should connect sources before drawing a measured implication.',transferZh:'綜合回應應先連結來源，再提出適度推論。'},
      's3-gb21':{focus:'Move from limited evidence to a proportionate next step',focusZh:'由有限證據推進至合乎比例的下一步',steps:['Read the sample size: 32 of 50 respondents, not every student.','Identify the pattern: a preference for a later closing time.','Choose a next evidence-gathering action, not a final decision.','Reject claims that make the poll representative of all families.'],stepsZh:['閱讀樣本數：50 名受訪者中的 32 名，並非所有學生。','找出趨勢：偏好較遲關閉時間。','選擇下一個蒐集證據行動，而非最終決定。','排除把調查視為代表所有家庭的主張。'],transfer:'A mature formal response turns limited evidence into a realistic review action.',transferZh:'成熟的正式回應會把有限證據轉化成實際的檢討行動。'},
      's3-gb22':{focus:'Qualify an online source before relying on it',focusZh:'引用網上來源前先作限定',steps:['The flyer makes a claim, but it is not automatically reliable.','Keep the useful content: it refers to a new rule.','Request traceable checks: the date and issuing organisation.','Reject certainty words such as certainly when those checks are missing.'],stepsZh:['海報提出主張，但不會自動可靠。','保留有用內容：它提及一項新規則。','要求可追溯核實：日期和發布機構。','缺少這些核實時，排除 certainly 等肯定字眼。'],transfer:'Source evaluation writing should name the exact reliability details a reader can verify.',transferZh:'來源評估寫作應說明讀者可核實的具體可靠性資料。'},
      's3-gb23':{focus:'Formal recommendation with a base-form passive',focusZh:'使用原形被動語態的正式建議',steps:['The observation data provides a reason for action at the gate.','The volunteers receive the assignment, so use a passive structure.','After recommends that, use the base-form passive be assigned.','Reject are assigned because the sentence gives a recommendation, not a present fact.'],stepsZh:['觀察資料為閘口行動提供理由。','義工接受分配，所以使用被動結構。','在 recommends that 後使用原形被動 be assigned。','排除 are assigned，因為句子提出建議，而非現在事實。'],transfer:'Formal proposals can use recommend that + subject + base form to state a precise action.',transferZh:'正式建議書可使用 recommend that + 主語 + 動詞原形，提出精確行動。'},
      's3-gb24':{focus:'Concession that keeps benefit and concern visible',focusZh:'同時保留好處與關注的讓步',steps:['Identify the benefit: crowding was reduced.','Identify the remaining concern: later collection time troubled some families.','Use Although to attach the benefit without cancelling the concern.','Reject therefore because the second clause does not state a result.'],stepsZh:['找出好處：擠擁已減少。','找出尚存關注：較遲接送時間令部分家庭感到困難。','用 Although 連結好處，同時不抹去關注。','排除 therefore，因為第二分句不是結果。'],transfer:'Balanced evaluations often use concession to prevent one positive result from silencing another need.',transferZh:'平衡評估常用讓步，避免一個正面結果掩蓋另一項需要。'},
      's3-gb25':{focus:'Evidence condition for a recommendation',focusZh:'建議的證據條件',steps:['Identify the action: extending the service.','Find the condition: attendance records must show consistent demand.','Match plural records with show.','Keep the condition after only if so the action is not automatic.'],stepsZh:['找出行動：延長服務。','找出條件：出席紀錄必須顯示持續需求。','複數 records 配合 show。','把條件放在 only if 後，說明行動不是自動進行。'],transfer:'Formal recommendations become more credible when they state the evidence required for action.',transferZh:'正式建議說明採取行動所需的證據時會更具可信性。'},
      's3-gb26':{focus:'Reporting an effect with measured certainty',focusZh:'以適度肯定程度報告效果',steps:['Notice the result occurred during only a four-week pilot.','Notice the missing comparison: no longer period has been checked.','Use appears to have reduced for a possible past effect.','Reject forever, proves and completely because they overstate the data.'],stepsZh:['留意結果只發生在四星期試行期間。','留意缺少比較：尚未檢視更長時段。','對可能的過去效果使用 appears to have reduced。','排除 forever、proves 和 completely，因為它們誇大資料。'],transfer:'A formal report should calibrate certainty to the duration, sample and comparison available.',transferZh:'正式報告應把肯定程度配合可得的時段、樣本和比較資料。'},
      's3-gb27':{focus:'Inversion for controlled formal emphasis',focusZh:'使用倒裝作受控制的正式強調',steps:['Find the paired structure: Not only ... but also.','After Not only, bring did before the subject.','Keep improve in the base form after did.','Use this structure sparingly to emphasise two linked outcomes.'],stepsZh:['找出配對結構：Not only ... but also。','在 Not only 後把 did 放在主語前。','did 後的 improve 保持動詞原形。','適量使用此結構以強調兩個相連結果。'],transfer:'Inversion can add controlled emphasis in a formal response when the logic is already clear.',transferZh:'當邏輯已清楚時，倒裝可在正式回應中加入適度強調。'},
      's3-gb28':{focus:'Nominalise an action for formal register',focusZh:'把行動名詞化以提升正式語體',steps:['The article a needs a noun phrase.','Choose analysis as the noun that names the action.','Use systematic to describe the analysis.','Reject options that keep analyse as a verb after a.'],stepsZh:['冠詞 a 後需要名詞片語。','選擇 analysis 作為命名行動的名詞。','使用 systematic 描述這項分析。','排除在 a 後仍保留動詞 analyse 的選項。'],transfer:'Nominalisation can package a process compactly in reports, provided the meaning stays concrete.',transferZh:'只要意思保持具體，名詞化可在報告中精煉地概括一個過程。'},
      's3-gb29':{focus:'Replace vague reference with named evidence',focusZh:'以具名證據取代含糊指代',steps:['Identify what This refers to: the 12% increase in sign-ins.','Name that evidence directly in the revised sentence.','Use may indicate to avoid treating one measure as proof.','Reject vague pronouns and claims about everyone.'],stepsZh:['找出 This 所指：登記次數增加 12%。','在修訂句中直接點出該證據。','使用 may indicate，避免把一項指標當作證明。','排除含糊代名詞和涉及所有人的主張。'],transfer:'Clear reference makes evidence chains easier for a reader or marker to follow.',transferZh:'清楚指代可令讀者或評閱者更容易追蹤證據脈絡。'},
      's3-gb30':{focus:'Conclude with a proportionate recommendation',focusZh:'以合乎比例的建議作結',steps:['Value the available evidence: student feedback is useful.','State the limit: not every family has been consulted.','Choose a next process: further consultation.','Reject final-decision language that the evidence cannot support.'],stepsZh:['重視已有證據：學生回饋有用。','說明限制：尚未諮詢每個家庭。','選擇下一個程序：進一步諮詢。','排除證據未能支持的最終決定語言。'],transfer:'A strong closing answers what should happen next and explains why the evidence is not yet final.',transferZh:'有力的結語會回答下一步應做甚麼，並解釋為何證據尚未足以作最終決定。'}
    }
  };
})();
